require_once dirname(__DIR__).'/configuracion/family.php';$parent=family_identity();app_db()->set_charset('utf8mb4');$childId=(int)app_value($_GET,'child');$child=family_child(family_children($parent),$childId);
$rows=app_rows('SELECT e.*,u.Nombre,u.Apellido1 FROM piscina_evaluaciones e JOIN alumnos a ON a.id_alumno=e.id_alumno LEFT JOIN usuarios u ON u.id_usuario=e.autor WHERE a.id_usuario=? AND e.publicada=1 ORDER BY e.fecha DESC,e.id DESC LIMIT 100','i',array($childId));
$old=app_rows('SELECT e.*,c.nombre AS curso_nombre FROM agenda_programacion_evaluaciones_estado_alumnos e JOIN alumnos a ON a.id_alumno=e.id_alumno AND a.id_curso=e.id_curso JOIN cursos_academicos c ON c.id_curso=a.id_curso WHERE a.id_usuario=? AND (COALESCE(e.estado,0)=1 OR COALESCE(e.estado_p1,0)+COALESCE(e.estado_p2,0)+COALESCE(e.estado_p3,0)+COALESCE(e.estado_p4,0)+COALESCE(e.estado_t1,0)+COALESCE(e.estado_t2,0)+COALESCE(e.estado_t3,0)>0) ORDER BY e.fecha_evaluacion DESC LIMIT 100','i',array($childId));
header('Content-Type: text/html; charset=UTF-8');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evaluaciones · Neo Kids</title><link rel="stylesheet" href="assets/pool.css?v=20260924"><link rel="manifest" href="/app/manifest.webmanifest"><link rel="stylesheet" href="/app/assets/portrait.css?v=20260930-1"><script src="/app/assets/portrait.js?v=20260930-1" defer></script></head><body><main class="family-main"><a class="back" href="./?child=<?php echo $childId; ?>">← Volver a sus clases</a><section class="family-hero"><span class="eyebrow">Cada avance cuenta</span><h1>Así va <?php echo app_escape($child['Nombre']); ?>.</h1><p>El seguimiento de su monitor o monitora.</p></section>
<?php foreach($rows as $r){ ?><article class="card"><span class="eyebrow"><?php echo date('d/m/Y',strtotime($r['fecha'])); ?></span><h2><?php echo app_escape($r['titulo']); ?></h2><p>Monitor/a: <?php echo app_escape(trim($r['Nombre'].' '.$r['Apellido1'])); ?></p><p class="message-text"><?php echo nl2br(app_escape($r['observaciones'])); ?></p></article><?php }
foreach($old as $r){$notes=app_rows('SELECT e.nota,e.periodo,e.trimestre,o.nombre_objetivo FROM agenda_programacion_evaluaciones_trimestrales e JOIN agenda_programacion_objetivos_piscina o ON o.id_objetivo=e.id_objetivo WHERE e.id_alumno=? AND e.id_curso=? AND ((?>0 AND e.periodo=?) OR (?=0 AND e.trimestre=?)) ORDER BY o.nivel,o.id_objetivo','iiiiii',array((int)$r['id_alumno'],(int)$r['id_curso'],(int)$r['periodo'],(int)$r['periodo'],(int)$r['periodo'],(int)$r['trimestre'])); ?><details class="card"><summary><?php echo app_escape($r['curso_nombre']); ?> · Evaluación <?php echo app_escape($r['periodo']?:$r['trimestre']); ?></summary><p class="message-text"><?php echo nl2br(app_escape(strip_tags($r['observaciones']))); ?></p><ul class="evaluation-list"><?php foreach($notes as $n){ ?><li><span><?php echo app_escape($n['nombre_objetivo']); ?></span><strong><?php echo app_value(array(0=>'No trabajada',1=>'Superada',2=>'Progresa'),(int)security_html($n['nota']),'Sin valoración'); ?></strong></li><?php } ?></ul></details><?php }if(!$rows&&!$old)echo '<section class="card empty"><h2>Sus primeros avances están por llegar</h2><p>Cuando el monitor publique una evaluación, podrás consultarla aquí.</p></section>'; ?></main></body></html>
